function parseMonthYear(value) {
  if (!value) return null;

  const startPart = value.split(' - ')[0].trim();
  const parts = startPart.split(' ');
  if (parts.length !== 2) return null;

  const monthMap = {
    jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5,
    jul: 6, aug: 7, sep: 8, oct: 9, nov: 10, dec: 11
  };

  const month = monthMap[parts[0].toLowerCase()];
  const year = parseInt(parts[1], 10);

  if (month === undefined || isNaN(year)) return null;

  return new Date(year, month, 1);
}

function getDateBucket(startDate) {
  if (!startDate) return '';

  const today = new Date();
  const diffMs = today - startDate;
  const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));

  if (diffDays < 90) return '<90 days';
  if (diffDays <= 180) return '90-180 days';
  return '>180 days';
}

return items.map((item, i) => {
  const raw = item.json.linkedinJobDateRange || '';
  const startDate = parseMonthYear(raw);
  const bucket = getDateBucket(startDate);

  return {
    json: {
      ...item.json,
      normalized_job_start: startDate
        ? startDate.toISOString().split('T')[0]
        : '',
      job_age_bucket: bucket
    },
    pairedItem: { item: i }
  };
});

// ============================================================
//  AiGS — Junior / Non-Decision-Maker Lead Filter
//  n8n Code node  ·  Mode: "Run Once for All Items"
//  Filters on the linkedinJobTitle field.
//  Keeps senior candidates, drops interns/students/junior/etc.
// ============================================================

// --- CONFIG ---------------------------------------------------

// Always disqualifies. Word-boundary matched, case-insensitive.
const HARD_EXCLUDE = [
  "intern", "summer", "incoming", "student", "undergraduate",
  "trainee", "apprentice", "junior", "jr", "extern", "externship",
  "fellow", "fellowship", "graduate", "candidate", "aspiring",
  "seeking", "retired", "volunteer", "server", "ambassador",
  "coop", "co-op", "seasonal", "rotational"
];

// Disqualifies ONLY when the title has no seniority marker below.
// Protects "Associate Vice President", "Assistant Director", etc.
// while still dropping "Sales Associate" and "Medical Assistant".
const CONDITIONAL_EXCLUDE = ["assistant", "associate"];

// A match here rescues a title from CONDITIONAL_EXCLUDE.
const SENIOR_MARKERS = [
  "vice president", "vp", "svp", "evp", "avp",
  "director", "managing director", "chief", "head of",
  "president", "partner", "principal", "controller",
  "officer", "ceo", "cfo", "coo", "cto", "cio",
  "cro", "cco", "cmo", "cdo"
];

// Blank title = can't classify. false = keep it, true = drop it.
const REMOVE_EMPTY_TITLES = false;

// --- ENGINE ---------------------------------------------------

const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const wordRe   = (w) => new RegExp("\\b" + escapeRe(w) + "\\b", "i");

const hardRes   = HARD_EXCLUDE.map(wordRe);
const condRes   = CONDITIONAL_EXCLUDE.map(wordRe);
const seniorRes = SENIOR_MARKERS.map(wordRe);

function isJunior(rawTitle) {
  const title = (rawTitle || "").trim();
  if (!title) return REMOVE_EMPTY_TITLES;

  // 1) hard excludes — checked first, always win
  if (hardRes.some((re) => re.test(title))) return true;

  // 2) conditional excludes — only if no seniority marker present
  const hasSenior = seniorRes.some((re) => re.test(title));
  if (!hasSenior && condRes.some((re) => re.test(title))) return true;

  return false;
}

// Keep only the senior candidates. pairedItem links are preserved.
return $input.all().filter(
  (item) => !isJunior(item.json.linkedinJobTitle)
);
